example.query:

# Buscar traduções de "hypertension" em múltiplos idiomas
SELECT ?item ?label_pt ?label_en ?label_ar ?label_zh WHERE {
  ?item wdt:P31 wd:Q12136.  # instance of disease
  ?item wdt:P493 "I10".     # ICD-10 code for hypertension
  OPTIONAL { ?item rdfs:label ?label_pt. FILTER(LANG(?label_pt) = "pt") }
  OPTIONAL { ?item rdfs:label ?label_en. FILTER(LANG(?label_en) = "en") }
  OPTIONAL { ?item rdfs:label ?label_ar. FILTER(LANG(?label_ar) = "ar") }
  OPTIONAL { ?item rdfs:label ?label_zh. FILTER(LANG(?label_zh) = "zh") }
}
LIMIT 1

